108→<script>
109→(function () {
110→  // Wait for app embed to set window.__zccAppEnabled.
111→  // App embed (target: body) may load after this section block, so we poll briefly.
112→  var maxWait = 3000; // ms
113→  var interval = 50;  // ms
114→  var elapsed = 0;
115→
116→  function tryInit() {
117→    if (window.__zccAppEnabled) {
118→      init();
119→    } else if (elapsed < maxWait) {
120→      elapsed += interval;
121→      setTimeout(tryInit, interval);
122→    }
123→    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
124→  }
125→
126→  // Start checking — if already set, runs immediately
127→  if (document.readyState === 'loading') {
128→    document.addEventListener('DOMContentLoaded', tryInit);
129→  } else {
130→    tryInit();
131→  }
132→
133→  function init() {
134→  var ROOT_ID = "zcc-widget-{{ block.id }}";
135→  var container = document.getElementById(ROOT_ID);
136→  if (!container) return;
137→
138→  var SHOP = container.dataset.shop;
139→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
140→
141→  // Try embedded config from metafield first (instant, no network needed)
142→  var configStr = container.getAttribute("data-config");
143→  if (configStr) {
144→    try {
145→      renderWidget(JSON.parse(configStr));
146→      return;
147→    } catch (e) {
148→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
149→    }
150→  }
151→
152→  // Fallback: fetch config from API
153→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
154→    .then(function (r) {
155→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
156→      return r.json();
157→    })
158→    .then(function (cfg) { renderWidget(cfg); })
159→    .catch(function (err) {
160→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
161→      renderWidget({});
162→    });
163→
164→  function renderWidget(cfg) {
165→    // Merge with defaults
166→    var D = {
167→      position: "inline",
168→      heading: "Check Delivery Availability",
169→      placeholder: "Enter your zip code",
170→      buttonText: "Check",
171→      successMessage: "Great news! We deliver to your area.",
172→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
173→      notFoundMessage: "We currently do not ship to this ZIP code.",
174→      primaryColor: "#008060",
175→      successColor: "#008060",
176→      errorColor: "#D72C0D",
177→      backgroundColor: "#FFFFFF",
178→      textColor: "#202223",
179→      borderRadius: "8",
180→      showEta: true,
181→      showZone: false,
182→      showWaitlistOnFailure: false,
183→      showCod: true,
184→      showReturnPolicy: true,
185→      showCutoffTime: true,
186→      showDeliveryDays: true,
187→      customCss: "",
188→      blockCartOnInvalid: false,
189→      showSocialProof: true,
190→    };
191→    Object.keys(D).forEach(function (k) {
192→      if (cfg[k] === undefined || cfg[k] === null) cfg[k] = D[k];
193→    });
194→
195→    var rad = cfg.borderRadius + "px";
196→    var WID = "zcc-" + ROOT_ID;
197→
198→    if (cfg.position === "floating") {
199→      renderFloating(cfg, WID, rad);
200→    } else if (cfg.position === "popup") {
201→      renderPopup(cfg, WID, rad);
202→    } else {
203→      renderInline(cfg, WID, rad);
204→    }
205→
206→    // If blockCartOnInvalid is enabled, disable ATC/Buy Now buttons on page load
207→    // until the customer validates their ZIP code
208→    if (cfg.blockCartOnInvalid) {
209→      blockCartButtonsInitial();
210→    }
211→  }
212→
213→  // ── Block ATC buttons on page load (before any ZIP check) ─────────────────
214→  function blockCartButtonsInitial() {
215→    var ATC_SELECTORS = [
216→      'button[name="add"]',
217→      '.product-form__submit',
218→      '[data-product-add]',
219→      '.btn--add-to-cart',
220→      '.product-form button[type="submit"]',
221→      'button.shopify-payment-button__button',
222→      '.shopify-payment-button button',
223→      'button.product-form__cart-submit'
224→    ].join(',');
225→
226→    function doBlock() {
227→      try {
228→        var atcBtns = document.querySelectorAll(ATC_SELECTORS);
229→        atcBtns.forEach(function(b) {
230→          if (!b.closest('[data-zcc-widget]')) {
231→            if (!b.getAttribute('data-zcc-blocked')) {
232→              b.setAttribute('data-zcc-orig-title', b.title || '');
233→            }
234→            b.disabled = true;
235→            b.style.opacity = '0.5';
236→            b.title = 'Please check ZIP code availability first';
237→            b.setAttribute('data-zcc-blocked', 'true');
238→          }
239→        });
240→      } catch(e) {}
241→    }
242→
243→    // Block immediately + delays for dynamic buttons (Shopify Buy Now renders late)
244→    doBlock();
245→    setTimeout(doBlock, 500);
246→    setTimeout(doBlock, 1500);
247→
248→    // MutationObserver for dynamic payment buttons
249→    if (typeof MutationObserver !== 'undefined') {
250→      var observer = new MutationObserver(function() { doBlock(); });
251→      var form = document.querySelector('.product-form, [data-product-form], form[action*="/cart/add"]');
252→      if (form) {
253→        observer.observe(form, { childList: true, subtree: true });
254→        setTimeout(function() { observer.disconnect(); }, 10000);
255→      }
256→    }
257→  }
258→
259→  // ── Scope custom CSS: auto-prefix selectors with widget container ID ──────
260→  function scopeCustomCss(rawCss, wid) {
261→    if (!rawCss) return "";
262→    // Strip </style> tags to prevent injection
263→    var css = rawCss.replace(/<\/style>/gi, "");
264→    var result = "";
265→    var i = 0;
266→    while (i < css.length) {
267→      // Skip whitespace
268→      while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
269→      if (i >= css.length) break;
270→      // Pass through @keyframes and @font-face unchanged
271→      if (css[i] === '@') {
272→        var atRule = "";
273→        var j = i;
274→        while (j < css.length && css[j] !== '{' && css[j] !== ';') { atRule += css[j]; j++; }
275→        var atName = atRule.trim().toLowerCase();
276→        if (atName.indexOf("@keyframes") === 0 || atName.indexOf("@font-face") === 0) {
277→          result += atRule;
278→          if (j < css.length && css[j] === '{') {
279→            var depth = 1; result += css[j]; j++;
280→            while (j < css.length && depth > 0) {
281→              if (css[j] === '{') depth++;
282→              if (css[j] === '}') depth--;
283→              result += css[j]; j++;
284→            }
285→          }
286→          i = j; continue;
287→        }
288→        // @media: scope inner rules
289→        if (atName.indexOf("@media") === 0) {
290→          result += atRule;
291→          if (j < css.length && css[j] === '{') {
292→            result += '{'; j++;
293→            // Collect inner content
294→            var depth = 1; var inner = "";
295→            while (j < css.length && depth > 0) {
296→              if (css[j] === '{') depth++;
297→              if (css[j] === '}') depth--;
298→              if (depth > 0) inner += css[j];
299→              j++;
300→            }
301→            result += scopeCustomCss(inner, wid);
302→            result += '}';
303→          }
304→          i = j; continue;
305→        }
306→      }
307→      // Regular rule: grab selector, prefix with #wid
308→      var sel = ""; var body = "";
309→      while (i < css.length && css[i] !== '{') { sel += css[i]; i++; }
310→      if (i < css.length) { i++; } // skip {
311→      var depth = 1;
312→      while (i < css.length && depth > 0) {
313→        if (css[i] === '{') depth++;
314→        if (css[i] === '}') depth--;
315→        if (depth > 0) body += css[i];
316→        i++;
317→      }
318→      if (sel.trim()) {
319→        // Split multiple selectors by comma and prefix each
320→        var selectors = sel.split(',').map(function(s) {
321→          s = s.trim();
322→          if (!s) return '';
323→          return '#' + wid + ' ' + s;
324→        }).filter(Boolean).join(', ');
325→        result += selectors + ' {' + body + '}';
326→      }
327→    }
328→    return result;
329→  }
