332→  function buildSharedCss(W, cfg) {
333→    return (
334→      // Spin animation for loading spinner
335→      "@keyframes zcc-spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}" +
336→      // Button icon/label structure
