388→  // ── Widget CSS ─────────────────────────────────────────────────────────────
389→  function buildWidgetCss(wid, cfg, rad) {
390→    var W = "#" + wid;
391→    var btnRadius = rad || "10px";
392→    return (
393→      "@keyframes zcc-slide-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}" +
394→      W + "{background:transparent !important;color:" + cfg.textColor + " !important;padding:0 !important;border:none !important;box-shadow:none !important;max-width:480px !important;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif !important;box-sizing:border-box !important}" +
395→      W + " *{box-sizing:border-box !important}" +
396→      W + " .zcc-heading{font-size:15px !important;font-weight:700 !important;letter-spacing:-0.01em !important;margin:0 !important;color:" + cfg.textColor + " !important;display:flex !important;align-items:center !important;gap:8px !important;padding-bottom:12px !important;border-bottom:1px solid rgba(0,0,0,0.06) !important;margin-bottom:12px !important}" +
397→      W + " .zcc-heading-icon{display:inline-flex !important;align-items:center !important;justify-content:center !important;width:28px !important;height:28px !important;border-radius:50% !important;background:linear-gradient(135deg," + cfg.primaryColor + "18," + cfg.primaryColor + "08) !important;flex-shrink:0 !important}" +
398→      W + " .zcc-heading-icon svg{width:14px !important;height:14px !important}" +
399→      W + " .zcc-search-bar{display:flex !important;flex-direction:row !important;gap:10px !important;align-items:stretch !important}" +
400→      W + " .zcc-input{flex:1 !important;min-width:0 !important;padding:12px 16px !important;font-size:14px !important;border:1.5px solid #e0e0e0 !important;border-radius:" + btnRadius + " !important;outline:none !important;background:#fafbfb !important;color:" + cfg.textColor + " !important;transition:border-color 0.2s,box-shadow 0.2s !important}" +
